import { useEffect, useRef, useState } from 'react'
import type { PDFDocumentLoadingTask, RenderTask } from 'pdfjs-dist'
import workerUrl from 'pdfjs-dist/build/pdf.worker.min.mjs?url'
import { i18n } from '@/lib/i18n'

/** Draw the generated bytes directly; no native PDF plugin or persisted URL. */
export default function PdfPreview({ file }: { file: Blob }) {
  const host = useRef<HTMLDivElement>(null)
  const [loading, setLoading] = useState(true)
  const [failed, setFailed] = useState(false)
  const [pages, setPages] = useState(0)
  useEffect(() => {
    let disposed = false
    let task: PDFDocumentLoadingTask | undefined
    const rendering = new Set<RenderTask>()
    const container = host.current
    container?.replaceChildren()
    setLoading(true); setFailed(false); setPages(0)
    void (async () => {
      try {
        const pdfjs = await import('pdfjs-dist')
        const bytes = new Uint8Array(await file.arrayBuffer())
        if (disposed) { bytes.fill(0); return }
        pdfjs.GlobalWorkerOptions.workerSrc = workerUrl
        task = pdfjs.getDocument({ data: bytes, enableXfa: false, useSystemFonts: true })
        const pdf = await task.promise
        if (disposed) return
        for (let number = 1; number <= pdf.numPages; number++) {
          const page = await pdf.getPage(number)
          if (disposed) return
          const viewport = page.getViewport({ scale: 1.5 })
          const canvas = document.createElement('canvas')
          canvas.width = Math.ceil(viewport.width); canvas.height = Math.ceil(viewport.height)
          canvas.className = 'mx-auto block h-auto w-full max-w-[900px] bg-white shadow-sm'
          canvas.setAttribute('role', 'img'); canvas.setAttribute('aria-label', i18n('pdf.page', { page: number, count: pdf.numPages }))
          const context = canvas.getContext('2d')
          if (!context) throw new Error('Canvas unavailable')
          container?.append(canvas)
          const render = page.render({ canvas, canvasContext: context, viewport })
          rendering.add(render)
          try { await render.promise } finally { rendering.delete(render) }
          if (disposed) return
          canvas.dataset.pdfPageRendered = String(number)
          setPages(number)
        }
        if (!disposed) setLoading(false)
      } catch {
        if (!disposed) { setFailed(true); setLoading(false) }
      }
    })()
    return () => {
      disposed = true
      for (const render of rendering) render.cancel()
      void task?.destroy().catch(() => undefined)
      container?.replaceChildren()
    }
  }, [file])
  return <section aria-label={i18n('pdf.preview')} aria-busy={loading} data-pdf-preview data-pdf-pages={pages}>
    {loading && <p role="status" className="p-3 text-sm opacity-70">{i18n('pdf.rendering')}</p>}
    {failed && <p role="alert" className="p-3 text-sm text-p-red">{i18n('pdf.preview-error')}</p>}
    <div ref={host} className="space-y-4" />
  </section>
}
